struct sk_buff *ipv6_frag_reassembly(struct sk_buff *skb, u32 user) {
    if (skb->len == 0)
        return skb;

    struct sk_buff *prev_skb = find_prev_fragment(skb);
    if (!prev_skb)
        return skb;

    struct sk_buff *clone_skb = skb_clone(skb, GFP_ATOMIC);
    if (!clone_skb || skb_headroom(clone_skb) < skb_headroom(skb)) {
        kfree_skb(clone_skb);
        return skb;
    }

    skb_reset_transport_header(clone_skb);

    if (check_memory_threshold(clone_skb)) {
        kfree_skb(clone_skb);
        return skb;
    }

    struct fragment_queue *fq = find_or_create_fragment_queue(user);
    if (!fq) {
        kfree_skb(clone_skb);
        return skb;
    }

    if (!queue_fragment(fq, clone_skb))
        return skb;

    if (!fq->all_fragments_received)
        return skb;

    struct sk_buff *reassembled_skb = reassemble_fragments(fq);
    if (!reassembled_skb)
        return skb;

    release_fragment_queue(fq);
    return reassembled_skb;
}

struct sk_buff *ipv6_gather_frags(struct sk_buff *skb, u32 user) {
    if (skb->len == 0)
        return skb;

    struct sk_buff *prev_skb = skb_clone(skb, GFP_ATOMIC);
    if (!prev_skb || skb_headroom(prev_skb) < sizeof(struct ipv6hdr)) {
        kfree_skb(skb);
        return NULL;
    }

    skb_reset_transport_header(prev_skb);

    struct frag_queue *fq = find_frag_queue(user);
    if (!fq) {
        fq = create_frag_queue(user);
        if (!fq) {
            kfree_skb(prev_skb);
            return skb;
        }
    }

    if (!queue_skb(fq, prev_skb)) {
        kfree_skb(skb);
        return skb;
    }

    if (fq->complete) {
        struct sk_buff *reassembled_skb = reassemble_skb(fq);
        release_frag_queue(fq);
        if (reassembled_skb)
            return reassembled_skb;
    }

    return skb;
}

