struct sk_buff *ipv6_gather_frags(struct sk_buff *skb, u32 user)
{
    struct sk_buff *prev_skb;
    struct sk_buff *clone;
    struct frag_queue *fq;

    if (skb->len == 0)
        return skb;

    prev_skb = find_prev_fragment(skb);
    if (!prev_skb)
        return skb;

    clone = skb_clone(skb, GFP_ATOMIC);
    if (!clone || skb_headroom(clone) < skb_headroom(skb)) {
        kfree_skb(clone);
        return skb;
    }

    skb_set_transport_header(clone, skb_transport_offset(skb));

    if (check_memory_threshold(clone))
        drop_old_fragments(user);

    fq = find_or_create_frag_queue(user, skb);
    if (!fq)
        return skb;

    if (queue_skb_in_frag(fq, clone) < 0)
        return skb;

    if (all_fragments_received(fq)) {
        struct sk_buff *reassembled = reassemble_skb(fq);
        if (reassembled) {
            release_frag_queue(fq);
            return reassembled;
        }
    }

    return skb;
}
